    addSplitButton(defaultDefinition: CommandDefinition, additionalDefinitions: CommandDefinition[], showLastUsed: boolean, id?: string/* = ""*/, positionID?: string/* = ""*/, isBefore?: boolean/* = true*/): SplitButtonControl | null;
