  /**
    Provides management of selection filters. Supports registration of
    workspace-scoped custom graphics sub-filters that appear as separate
    entries in the selection filter dropdown, and querying or toggling the
    enabled state of any selection filter category visible in the toolbar.
    Access via {@link Workspace.selectionFilterSettings}.
    @experimental
    @permissions ui
    */
  export class SelectionFilterSettings extends Base {
    /**
      Registers a custom graphics selection sub-filter for this workspace.
      The filter matches custom graphics entities whose id starts with the
      given prefix and appears as a separate entry in the selection filter dropdown.
      @param displayName The user-visible name shown in the selection filter dropdown.
      @param idPrefix The prefix to match against each custom graphics entity's id property.
      @returns Returns true if the filter was registered successfully, or false if a
      filter with the same displayName is already registered for this workspace.
      */
    registerCustomGraphicsFilter(displayName: string, idPrefix: string): boolean;
    /**
      Unregisters a previously registered custom graphics selection sub-filter.
      @param displayName The display name of the filter to remove.
      @returns Returns true if the filter was found and removed, false otherwise.
      */
    unregisterCustomGraphicsFilter(displayName: string): boolean;
    /**
      Returns the names of all selection filter categories currently registered
      in the application. These names can be used with the isFilterEnabled and
      setFilterEnabled methods to query or toggle individual filters.
      */
    readonly availableFilters: string[];
    /**
      Gets whether a selection filter category is currently enabled.
      @param filterId The name of the selection filter category, as returned by the
      availableFilters property.
      @returns Returns true if the filter is enabled, false if it is disabled.
      An error occurs if the filterId does not match any available filter.
      */
    isFilterEnabled(filterId: string): boolean;
    /**
      Enables or disables a selection filter category.
      @param filterId The name of the selection filter category, as returned by the
      availableFilters property.
      @param enabled True to enable the filter, false to disable it.
      @returns Returns true on success. An error occurs if the filterId does not
      match any available filter.
      */
    setFilterEnabled(filterId: string, enabled: boolean): boolean;
    /**
      Gets or sets the Select Through option. When enabled, clicking
      selects through all overlapping entities rather than only the
      closest one.
      */
    isSelectThroughEnabled: boolean;
    /**
      Gets or sets whether all selection filter categories are enabled.
      The getter returns true only when every category is enabled.
      The setter enables or disables all categories at once.
      */
    areAllFiltersEnabled: boolean;
  }

  /**
    Provides access to and control over the set of selected entities in the user interface.
    @permissions ui
    */
  export class Selections extends Base {
    /**
      Returns the specified selection using an index into the collection.
      @param index The index of the item within the collection to return. The first item in the collection has an index of 0.
      @returns Returns the specified item or null if an invalid index was specified.
      */
    item(index: number /*unsigned int*/): Selection | null;
    /**
      Gets the number of entities currently selected.
      */
    readonly count: number /*unsigned int*/;
    /**
      Gets or sets all entities currently selected.
      */
    all: ObjectCollection | core.Base[];
    /**
      Adds the entity to the set of currently selected entities.
      The user will see the entity become selected in the user interface.
      @param entity The entity to select and add to this selection set.
      @returns Returns true if successful.
      */
    add(entity: Base): boolean;
    /**
      Clears the selection set so no entities are currently selected.
      @returns Returns true if successful.
      */
    clear(): boolean;
    /**
      Removes the specified selection from the set of selected entities.
      @param selection The selection to remove.
      @returns Returns true if the item was removed or not currently selected.
      */
    removeBySelection(selection: Selection): boolean;
    /**
      Removes the selections that are associated with the specified entity from the set of selected entities.
      @param entity The entity to remove selections of.
      @returns Returns true if the item was removed or not currently selected.
      */
    removeByEntity(entity: Base): boolean;
    /**
      Removes an item from the set of selected entities.
      @param index The index of the selection to remove.
      @returns Returns true if the item was removed successfully.
      */
    removeByIndex(index: number /*int*/): boolean;
    /**
      Returns an array containing all of the current selections. This is
      useful in cases where you need to iterate over the set of selected entities but need
      to create or edit data as you process each one. Selections are fragile and creation and
      edit operations will clear the selections so you won't have access to the complete list
      after processing the first one.
      @returns Returns an array of all of the current selections. Selection objects are returned so
      you'll need to call their entity properties to get the actual selected entity.
      */
    asArray(): core.Selection[];
    [Symbol.iterator](): BaseIterator;
  }
  abstract class BaseIterator implements Iterator<core.Base>{
    next(): IteratorResult<core.Base, boolean | undefined>
  }

